INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Aheya kahāpan ma a\'a sasuku mbal ameya\' gara\' min a\'a jahulaka\', sasuku isab mbal pasehe\' ma a\'a pangandusa. Mbal iya palamud ma saga a\'a ya angandali\'it Tuhan,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'saguwā\' kahōpan iya ma sara\' ya panoho\'anna ma manusiya\'. Ya he\' kinannal e\'na llaw-sangom.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'A\'a inān sali\' sapantun kayu tinanom ma bihing sapa\', ya amuwan buwa\' ma musimna du. Minsan painay mbal pak\'llos dahunna. Ai-ai hinangna, ahāp sadja tungbasna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Malaingkan saga a\'a jahulaka\' mbal buwattē\'. Sapantun sigām hampa\' pai ya tabowa paleyang e\' baliyu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Ya he\' sababna angkan saga a\'a jahulaka\' mbal makara\'awa bang ta\'abut nihukum, mbal isab pinalamud ma sasuku abontol atayna tudju ni Tuhan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Saga a\'a abontol niayura na pa\'in e\' PANGHŪ\' -Yawe, sagō\' saga a\'a jahulaka\' ala\'at sadja kat\'kkahan sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Angay angkan magbantu saga kabangsa-bangsahan, angay sigām magisun ma halam aniya\' pūsna?');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Magsakap di-sigām saga kasultanan, magsakaum saga pagnakura\'an bo\' angatu ma PANGHŪ\' -Yawe, maka ma Al-Masi ya tapene\'na.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Maghimumungan saga a\'a inān, yuk-i, “Gom kitam papuwas min komkoman sigām, gom b\'kkattam saga kili-kili ya pangengkot sigām.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Saguwā\' pagtittowahan sigām he\' Tuhan, ya aningkō\' ma sulga\' magkabaya\'an ma kamemon. Pinagtunggīngan sigām e\' Panghū\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Pinabukagan saga a\'a inān kabowa pangastolna, pinakitāw sigām ma sabab landu\' akagit atayna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Yuk Tuhan ma sigām, “O\'o, sultan bay tapatingkō\'ku, ina\'an ma Būd Siyun, ya būd kamulliyahanku.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Ya panambung sultan e\', “Pasaplagku lapal ya pangallam aku he\' PANGHŪ\'.” Yukna ma aku, “Ka\'a ilu tahinang anakku na. Aku ya Mma\'nu tinagna\'an min llaw itu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Bang aku ya pangamu\'annu, pamusaka\'ku ma ka\'a kamemon bangsa, pamasuku\'ku ma ka\'a sakalibutan dunya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Ka\'a ya amarinta ma kabangsa-bangsahan, ati apaslod pamarintanu sapantun tungkud basi\'. Alopot sigām kamemon sali\' dalil paliyuk.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Angkan yukku ma ka\'am saga sultan, “Pata\'u kam. Pahalli\' kam, sasuku magbabaya\' ma babaw dunya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Magpatireyo\' kam ma PANGHŪ\', pagkoyaginbi iya hinabubi magpamidpid.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Pasiyum kam ma Anakna, ya aniya\' kakagit atayna, ati taggaha\' kam t\'kkahan mulka\'na. Sabab pasulapput astolna saru\'un-du\'un, malaingkan aheya kahāpan ma sasuku makabāk patapukan ma iya.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'O Yawe, aheka saga a\'a amantahan aku! Kapilahan aku e\' saga a\'a magpanagga\' aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Aheka isab saga a\'a anunggīngan aku, yuk-i, “Mbal iya pinuwas e\' Tuhan min kamulahan.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Saguwā\' ka\'a ya tampanku, O PANGHŪ\'. Ka\'a ya amuwanan aku kasahaya\'an. Ka\'a ya amahogot kamahaldika\'anku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Bang aku parahing ni PANGHŪ\' -Yawe, sinambungan aku e\'na min būdna mulliya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Ahāp e\'ku atuli, asannang isab kabati\'ku, sabab binogbogan aku e\' PANGHŪ\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Mbal aku tināw ma saga bantaku ibu-ibuhan, ya angalibutan aku ma paruruwambila\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Ya PANGHŪ\', pasa\'ut ka, lappasun aku min ka\'aniban. Suntukun palbantahanku ma baihu\' sigām, paglopotun empon sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Si Yawe ya angaliyusan aku min kamulahan. Bang pa\'in buwanannu kahāpan saga a\'a suku\'nu.');
