INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'O Yawe, ka\'a pagpanghū\'an kami, kaheya du pa\'in mahaltabatnu ma kaluha\'an dunya! Alanga sahayanu min kapitu\' lapis langit.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Min kahandaknu saga kamanahutan amudji ōnnu, saga anak duru\'an lagi\' ananglitan ka\'a. Angkan mbal maka\'atu saga palbantahan, mbal makatukas saga magbabalos.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Ya PANGHŪ\', bang aku pahangad ni langit bo\' angira-ngira kahinangan tangannu, bang nda\'ku bulan maka saga bitu\'un ya bay pat\'nna\'nu ma b\'ttong langit,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'tabowa aku atilaw pasal kami manusiya\'. Ai kapūsan kami angkan kami pagka\'inagonannu? Angay kannalnu bangsa manusiya\' ya mbal anatas itu?');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Pat\'nna\'nu kami areyo\' dangkuri\' min saga bangsa mala\'ikat ya porol ma sulga\'. Buwanannu kami kasanglitan maka kabantugan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Buwanannu kami kapatut magbaya\' ma kamemon ai-ai bay paniya\'nu, bo\' kami makapagnakura\' ma kamemon papanjarihan,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'saga sapi\' maka saga bili-bili, hayop ni\'ipat, maka saga sattuwa talun.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Makapagagi kami ma saga manuk-manuk, maka ma kaginisan daing tahik maka sattuwa dilaut.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'O Yawe, ya pagpanghū\'an kami, kaheya du pa\'in mahaltabatnu ma kaluha\'an dunya!');
