INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'O Yawe, sumiyan aku patandung pabalik ni ataynu? Sumiyan ka pabaihu\' ni aku pabīng?');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Sumiyan bahā\' pahondong kalengog pikilanku itu, sabab llaw-sangom pasangdan na pa\'in kasusahanku. Sumiyan pahali saga bantaku anganda\'ug min aku?');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'O Yawe, Tuhanku, palingi\' gi\' ka anambungan aku. Pasawahun pang\'nda\'ku, da\'a aku pasagarin amatay.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Sabab bang aku mbal dūlannu, tantu aku niudju\' e\' kuntaraku, yuk-i, “Nē! Tara\'ug na ka!” Ati magkalasigan saga banta ma sabab kaiya\'anku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Saguwā\' angandol sadja aku ma kasi-lasanu tuman, maka magkōg-koyag ma sabab kapanglappasnu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'O PANGHŪ\', magkalang aku ni ka\'a, sabab kahāpnu ma aku mbal tapula\'-pula\'.');
