INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Ya Tuhan, hampanin aku, sabab ka\'a ya patapukanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Yukku ni si Yawe, “Ka\'a ya Panghū\'ku, Halam aniya\' palsuku\'anku ahāp saddī min ka\'a.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Babantugun saga a\'a ma lahat itu, ya atotog ameya\' ma kabaya\'an Tuhan. Landu\' aku kasulutan ma sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Malaingkan bang a\'a ameya\' ma tuhan-tuhan saddī, pak\'nnop na pa\'in kasusahan sigām. Mbal aku palamud ma a\'a inān anukbal laha\', mbal minsan sibahatku ōn saga pagtuhanan sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Ka\'a PANGHŪ\', sapantun pusaka\'ku, Ka\'a ya palsuku\'anku, ahāp kasōngan ya pangangganta\'nu ma aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Kabuwanan aku tana\' ma lahat kasalamatan, landu\' ahāp ya pamusaka\'nu aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Sanglitanku si Yawe ya angahūgan aku gara\'. Minsan ma waktu sangom, kapandu\'an aku luwas min pandu\' ya ma deyom pangatayanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Si Yawe ya pataptap ma pangatayanku. Itiya\' iya ma bihingku, angkan aku mbal tabowa pajudjal.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Magkōg-koyag aku sampay min deyom atay, asalamat pamarananku,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'sabab mbal aku siya-siyanu ma deyom ahirat. Mbal aku pasagarannu angahalu\' ma deyom paliyangan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Tantu aku tuli\'annu lān ya amowa ni kallum. Sinōd aku kōg-koyag ma sabab kamaitunu ma aku, kahōpan aku e\' kalasigan ya anatas ni kasaumulan bang ta\'abutku na haddaratnu.');
