INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'O Tuhanku, angay aku siya-siyanu? Angay ka palawak na pa\'in min aku? Angay halam takalenu pangandahingku?');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'O Tuhanku, anganjunjung aku ni ka\'a kahaba\' llaw, saguwā\' mbal aku sambungannu. Angamu\'-ngamu\' aku ni ka\'a kahaba\' sangom, sagō\' halam aniya\' halianku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Malaingkan ilu ka aningkō\' ma deyom kamahaldika\'an. Ka\'a ya Tunggal Mahasussi, ya pinudji e\' bangsa Isra\'il.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Bay angiman ma ka\'a saga kamatto\'ahan kami, bay sigām pasangdol ni ka\'a ati liyusannu min kasigpitan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Bay sigām parahing ni ka\'a, ati lappasannu, bay sigām angandol ma ka\'a, ati halam karapatan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Saguwā\' aku itu sali\' kalog tana\', sali\' ngga\'i ka manusiya\'. Niudju\' aku he\' pagkahiku, nihalipulu e\' kampungku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Pinakaiya\' aku he\' sasuku ang\'nda\'. Nihina\' aku, pinagelong-elongan, pinagtunggīng.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Ya lling sigām ma aku, “A\'a itu angandol ma si Yawe, na, patabangta iya ma PANGHŪ\' -Yawe. Kalu iya pinuwas min kasigpitan, pagka aheya lasa PANGHŪ\' ma iya.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Malaingkan, Tuhanku, ka\'a ya bay amaluwas aku min kulunan ina\'ku. Tabowa aku angandol ma ka\'a min kariki\'-diki\'ku gi\', min waktuku onde\' duru\'an lagi\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Ka\'a ya kaholatanku min llaw kapaganak ma aku, ka\'a ya Tuhanku sangay min kapangiram ma aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Da\'a kono\' ka pala\'an min aku, sabab itiya\' aku marai\' taluwa\' kasusahan. Luwal ka\'a ya makatabang.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Sikapūn-pūnan ni aku ba\'anan palbantahanku, sapantun sapi\' mandangan min lahat Basan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Pinabanga\' bowa\' sigām tudju ni aku, sapantun halimaw marai\' na an\'kkob, an\'kkat.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Angalongkoy anggauta\'ku, magsalisi\' lullun to\'olangku. Angalunuk atayku, ibarat lansuk atunaw e\' pasu\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Katoho\'an k\'llongku, buwat katoho\' buli\' lapohan. Angakkot d\'lla\'ku ni isi emponku, tahinangnu aku anginam bagunbun nalka\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Aniya\' sapantun ero\' ma sakalibutku, pinagtipunan aku he\' a\'a jahulaka\'. Nilagbas e\' sigām tape\'-tanganku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Ta\'nda\'an di-na bokogku kamemon, pinatong aku e\' saga a\'a ab\'nsihan aku, kinōgan sigām ma kala\'at pangluwahanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Pinagbahagi\'an s\'mmekku he\' sigām, pinagko\'ot-ko\'ot badju\'ku bang sai makarapu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Ya PANGHŪ\', da\'a pa\'in ka palawak min aku. Ka\'a ya ga\'osanku, bang pa\'in ka pasa\'ut anabang.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Tampanin aku bo\' mbal taōk e\' kalis. Ahalga\' ma aku nyawaku, angkan amu\'ku pinuwas min kosog saga ero\' itu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Liyusun aku min bowa\' halimaw, papuwasun aku min tanduk sapi\' talun.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Ati pasaplagku ōnnu ni dauranakanku, pudjiku ka ma palhimpunan saga jama\'anu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Ka\'am ya magmatāw ma si Yawe, pudjihunbi! Ka\'am saga panubu\' si Yakub, pagmahaltabatinbi! Ka\'am bangsa Isra\'il kamemon, hulmatunbi!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Sabab halam pabiyalna pagdahing saga a\'a asukkal, halam bay pasagaranna ma deyom kasigpitan. Halam bay taikutanna sasuku angamu\'-ngamu\', gom pa\'in tabangna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'O Tuhan, ka\'a ya pagpudjihanku ma palhimpunan aheya, suhulku isab najalku ma matahan saga a\'a magmatāwan ka\'a.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Amangan saga miskin ma sinosōng sampay sigām asso. Sasuku kam angangut ma si Yawe ananglit du ma iya. Mura-murahan, bang pa\'in kam allum saumul-umul.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Kinannal si Yawe he\' a\'a kamemon ma mpat pidju alam itu, ati papinda sigām magta\'at ni iya. Magpudji sabarang bangsa ma alopanna,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'sabab PANGHŪ\' -Yawe ya tag-parintahan ma dunya. Iya ya makapagagi ma kabangsa-bangsahan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Sasuku taga-karaya ma dunya itu, sigām balkanan, pasujud du ma alopan Tuhan. Sasuku amole\' lahat kamatayan magpatireyo\' ma iya, sampay saga a\'a ya mbal makapakalluman di-sigām, pasujud du.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Ni\'isbat Tuhan e\' panubu\' magsuring-magsaingsing, pinandu\'an sigām pasal si Yawe ma sinosōng.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Ati sigām ya pas\'lle\' amatanyag ni saga a\'a halam gi\' palahil pasal kabontolan ya tahinang e\' Tuhan ma sabab a\'a suku\'na.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Si Yawe ya angipat aku, sapantun a\'a angipat bili-bilina, angkan halam aniya\' kulang ma aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Kahinangan aku he\'na pahalian ma parang-parang alunuk, niambit aku he\'na ni atag bohe\' kasannangan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Pinahayang nyawaku, minaliman aku he\'na ma lān abontol, ma sabab Ōnna kabantugan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Minsan palabayanku kal\'ddoman lambung kamatay, mbal aku atāw pinuhinga\' sabab ka\'a ya gapi\'ku, O Tuhan. Ilu tungkudnu maka soha\'nu amuwanan aku kasalamatan baran.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Sakapannu aku jamuhan ma alopan palbantahanku. Ni\'ns\'llanan he\'nu kōkku, tanda\' sin lasanu ma aku. Palasay sawanku pagka ap\'nno\' he\' pahala\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Tantu aku pinasuku\'an kahāpan, tantu tinogolan lasanu ma aku sat\'ggolku allum. Ati luma\' PANGHŪ\' ya pat\'nna\'anku saumul-umul.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Suku\' PANGHŪ\' dunya itu sampay kapanyapanna. Suku\'na alam itu sampay kabangsa-bangsahanna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Pinat\'nna\' e\'na gintana\'an ma t\'ngnga\' s\'llang, pinahogot he\'na ma t\'ngnga\' kas\'llogan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Sai bahā\' makatukad ni būd PANGHŪ\'? Sai bahā\' makat\'ngge ma deyom luma\' pangarapan ni iya?');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Luwal a\'a ya asussi tanganna min dusa, ya apote\' deyom pangatayanna. Luwal isab a\'a ya mbal anumba ni ta\'u-ta\'u, maka mbal magsapa pagputingan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Makasambut pahala\' min PANGHŪ\' bang a\'a buwattē\' kajarihanna. Tinungbasan iya kabontolan itikad e\' Tuhan Manglalappas.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Buwattē\' isab kahālan saga a\'a ya angangut Tuhan, ya atuyu\' paharap ni ka\'a, O Tuhan si Yakub.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Bang pa\'in paukab saga tambol! Bang pa\'in paukab saga lawang awal-jaman, bo\' supaya makasōd Sultan Sanglit-sahaya!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Sai sa Sultan Sanglit-sahaya itu? Si Yawe ko\' itu, ya landu\' akosog, landu\' aesog. PANGHŪ\' ko\' itu, ya makaga\'os ma pagbono\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Bang pa\'in paukab saga tambol! Bang pa\'in paukab saga lawang awal-jaman, bo\' supaya makasōd Sultan Sanglit-sahaya!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Sai sa Sultan Sanglit-sahaya itu? Si Yawe ko\' itu, ya Sangat Kawasa. Ya na Sultan Sanglit-sahaya!');
