INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Si Yawe ya amuwanan aku kasawahan maka kalappasan, angkan halam aniya\' katāwanku. PANGHŪ\' -Yawe ya sapantun kuta\' pangahampan kallumku, angkan halam aniya\' kagawahanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Bang aku sinekot e\' a\'a jahallis, ya bilahi angamula baranku, bang aku nirugpak e\' ba\'anan bantaku, tantu sigām makarugtul, makahantak.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Minsan aku nilikusan he\' tumpukan ba\'anan sundalu, mbal kin\'bba-k\'bba atayku. Minsan aku t\'kkahan pagbono\', ahantap na pa\'in pangatayanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Luwal itu ya pangamu\'ku ni PANGHŪ\' -Yawe, luwal itu ya pagmatayanku, bang pa\'in aku paokom ma luma\' Tuhan sat\'ggolku allum ma babaw dunya itu. Landu\' aku bilahi ang\'nda\' ma kahāp palantarana, maka angaruhan iya ma luma\'na pangarapan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Angkan buwattē\', sabab tinampanan aku he\'na ma waktu katumbuk kasusahan. Pinakuta\'an aku e\'na ma pussuk batu-lakit, tinapukan aku sakuli-kuli ma luma\' pagtata\'atan ni iya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Minnē\' aku anganda\'ug min palbantahanku, pinalanga aku min saga banta ma katilibutku. Tukbalanku pagkulban ni PANGHŪ\' -Yawe ma langgal ya pangarapan iya, hinabuku angolang kabowa kakōganku. Angalang isab aku, pagpudjiku PANGHŪ\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'O PANGHŪ\', kalehun lagi\' panganjunjungku, ka\'ase\'in aku, sambungin aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Ah\'llingan aku di-ku, “Panuyu\'in si Yawe.” Jari patuyu\' aku ma ka\'a, O PANGHŪ\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Da\'a kono\' ka pataikut min aku sabab sosoho\'annu aku. Da\'a pa\'in akagit ataynu, da\'a aku taikutin, sabab ka\'a ya pananabang ma aku. Da\'a aku palehomun, da\'a aku bbahin, sabab ka\'a ya Tuhanku Manglalappas.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Abila aku siniya-siya he\' ina\'-mma\'ku, tantu aku tinaima\' e\' PANGHŪ\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Ya, PANGHŪ\', pandu\'in aku lānnu, ya amowa ni kahāpan. Malimin aku ma lān abontol, sabab aheka a\'a angangut angala\'at aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Da\'a aku pasagarin pinagbaya\'an e\' saga kuntaraku, sabab aniya\' a\'a anuna\'an aku kaputingan. Ya kab\'ngngis sigām mbal kaliyuhan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Saguwā\' minsan buwattē\', aniya\' kaholatanku tuman. Tantu aku makabāk kahāpan min si Yawe, hinabuku lagi\' ma dunya dakayu\' itu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Angkan yukku, “Pangasahin si Yawe. Pahogotunbi imanbi, pataptapunbi pangatayanbi, pangaholatinbi PANGHŪ\' -Yawe.”');
