INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Aheya kahāpan ma sasuku niampun kala\'atanna, sasuku pinapasan paldusahanna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Aheya kahāpan ma sasuku abontol ma bistahan PANGHŪ\', sasuku halam aniya\' kaputingan ma pangatayanna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Sat\'ggol limbunganku dusaku, anitis na pa\'in bokogku ma sabab pangandahingku kahaba\' llaw.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Kabuhatan aku llaw-sangom, sali\' kahantang tangannu ya makabuhat. Angalongkoy kuwat-anggauta\'ku, buwat a\'a apanggang ma musim pang\'llaw.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Malaingkan bay tapamattanku dusaku ni ka\'a, halam bay limbunganku kala\'atanku. Yukku, “Gom aku magpasab\'nnal ni PANGHŪ\',” magtūy ta\'ampunnu kasā\'anku kamemon.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Angkan sasuku magtata\'at subay angamu\'-ngamu\' ni ka\'a ma waktu kahanggawna. Bang pasōng kasusahanna sapantun latap alalom, mbal iya alimun he\' susa.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'O Tuhan, ka\'a ya patapukanku, ka\'a ya angahampanan aku min kajahatan. Alibut aku e\' saga a\'a magkalangan aku ma sabab kalappasnu ma aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Yuk Tuhan ni aku, “Pandu\'anta ka lān ya wajib palabayannu. Hūganta ka gara\' ati peyananku ka.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Da\'a ka pasali\' ni kajarihan kura\', ya halam aniya\' akkalna. Mbal tasoho\' hayop inān, mbal tapasekot ni ka\'a, luwal bang sangonannu kakkang maka engkot.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Aheya karukka\'an saga a\'a ya ala\'at kajarihanna, saguwā\' sasuku angandol ma si Yawe, ap\'nno\' iya e\' kasi-lasa PANGHŪ\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Kalasiginbi si Yawe. Pakoyag kam sasuku ahāp kajarihanbi. Magkalang kam sasuku abontol itikadbi.');
