INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Da\'a kahanggawinbi saga a\'a jahulaka\', da\'a isab pangihirinbi saga a\'a maghinang kala\'atan!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Sapantun sigām parang-parang al\'kkas alanos, sapantun dahun ak\'llos magdai\'-dai\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Angandol sadja kam ma PANGHŪ\' -Yawe, hinangunbi kahāpan. Pat\'nna\' kam ma lahatbi porol, pat\'nna\' kam ma deyom kasannangan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Paglasiginbi PANGHŪ\' ati kabuwanan kam ai-ai ya makasulut pangatayanbi.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Pama\'andolunbi kahālanbi ni PANGHŪ\', pasangdolinbi iya, ati tahinang e\'na ya amu\'bi.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Pinabukis he\'na ka\'adilanbi, sapantun sawa ya pabukis dai\'-llaw, pinasaplag kabontol palkala\'bi, sapantun sinag llaw bang augtu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Pat\'mmun kam ma alopan si Yawe, lagarinbi iya. Da\'a kam asusa bang auntung saga a\'a kasehe\'an, bang tahinang kagara\'an sigām ajahallis.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Da\'a kam angastol! Da\'a kam angamahit! Da\'a papasu\'un ataybi, tantu ala\'at kat\'kkahanna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Sabab pinahalam saga a\'a ala\'at kajarihanna, saguwā\' sasuku angasa ma PANGHŪ\' pinusaka\'an lahat itu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Mbal at\'ggol, pahalam saga a\'a ala\'at itu. Minsan painay e\'bi amiha, mbal tabāk.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Sagō\' saga a\'a areyo\' pangatayanna pinasuku\'an lahat itu, ati halam aniya\' makasasaw kasannangan sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Binantuhan a\'a ahāp atayna he\' a\'a jahulaka\'. Ang\'ttop le\'e saga a\'a inān, tanda\' sin kab\'nsi sigām ma a\'a ahāp.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Malaingkan pinagtittowahan he\' PANGHŪ\' saga a\'a jahulaka\', sabab kata\'uwanna aniya\' llaw pangangganta\' ma sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Angahublut kalis saga a\'a jahulaka\', anakap ba\'ugan pana\' sigām, bo\' tapana\' e\' sigām saga a\'a kamiskinan maka kasigpitan. Ya maksud sigām amapatay saga a\'a abontol atayna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Saguwā\' papelleng kalis inān angandugsu\' jantung sigām, pinagpōng-pōng isab saga ba\'ugan pana\' sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Minsan akulang ai-ai ya palsuku\'an ma saga a\'a abontol, labi ahalga\' ko\' inān min alta\' manglabi-labihan ya palsuku\'an saga a\'a ala\'at.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Sabab pahalam ya ga\'osan saga a\'a jahulaka\', sagō\' angandapit PANGHŪ\' -Yawe ma saga a\'a abontol palangayna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Niayuput e\' si Yawe kallum sasuku mbal katōngan dusa ati anatas pusaka\' sigām sampay ni kasaumulan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Mbal sigām aiya\' bang t\'kkahan kasigpitan. Minsan ma waktu gotom, maka\'ssohan kinakan sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Malaingkan saga a\'a jahulaka\' magka\'at lullun. Palanyap saga palbantahan PANGHŪ\', ibarat humbu. Ibarat sigām kalingkat sumping ya patomo\' ma deya, dai\'-dai\' du palanos bo\' halam na.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Angutang saga a\'a ala\'at sagō\' mbal amayad. Saguwā\' saga a\'a ahāp magmura sadja,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'sabab sai-sai kabuwanan pahala\' he\' PANGHŪ\' pinusaka\'an lahat itu. Saguwā\' sai-sai sinapdahan e\' PANGHŪ\', tantu magmula.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Bang kasulutan PANGHŪ\' ma kaul-pi\'il a\'a, pinatotog e\'na tekangna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Minsan iya makarugtul, mbal tabowa pahantak, sabab PANGHŪ\' -Yawe ya amalutan tanganna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Min kaonde\'-onde\'ku sampay ni kato\'aku itu, halam aniya\' a\'a abontol bay ta\'nda\'ku pinasagaran he\' Tuhan. Halam isab ta\'nda\'ku anak a\'a inān tabowa angamu\' kinakan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Magmura sadja sigām amuwan maka amautang, angkan pinaniya\'an pahala\' saga anak sigām e\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Angkan yukku, pataikut kam min kala\'atan bo\' patukid ma kahāpan, ati taptap kam pat\'nna\' ma lahatbi porol.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Angkan buwattē\', sabab kasulutan PANGHŪ\' ma a\'a angahinang kabontolan. Mbal palehomna saga a\'a ya atukid angisbat iya. Nihampanan e\'na saga a\'a suku\'na sampay ni kasaumulan, saguwā\' bin\'kkat e\'na napas saga a\'a maghinang kala\'atan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Pamusaka\' ma a\'a ahāp ya lahat sigām porol, ati maglahat sigām maina\'an salama-lama tahun.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Bang a\'a asussi pangatayanna, amissala iya pangita\'u, abontol maka asaltun himumūnganna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Ina\'an ma deyom atayna sara\'-manara\' min Tuhanna, angkan mbal parasdas tape\'na.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Tinipu saga a\'a ahāp palangayna he\' a\'a ala\'at, sabab angamohot amapatay,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'saguwā\' mbal pinasagaran he\' si Yawe saga a\'ana gina\'os he\' a\'a jahulaka\'. Bang sigām pinaharap ni huwis, mbal tugutanna sigām taluwa\' hukuman.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Pangaholatinbi PANGHŪ\', bogboginbi panoho\'anna ati pinalanga kam bo\' pinusaka\'an lahatbi porol. Song isab ta\'nda\'bi saga a\'a jahulaka\' pinahalam.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Aniya\' bay ta\'nda\'ku a\'a landu\' ajahat maka abigsi\', ahāp sadja kahālanna, sapantun kayu alabung dahunna, ya patomo\' ma tana\' bay asal patomo\'anna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Sagō\' da\'a ka pilang\'llaw paglabayku minnē\', na halam na. Minsan painay he\'ku amiha iya, halam to\'ongan tabākku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Kira-kirahunbi a\'a halam dusahan, pangli\'unbi a\'a abontol palangayna, sabab ahāp kasōngan ma saga a\'a mbal bilahi maglugat.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Saguwā\' tantu pinaka\'at kamemon saga baldusa, halam aniya\' kasōngan a\'a maghinang kala\'atan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Lappasan sasuku asussi pangatayanna, sabab min PANGHŪ\', ya sapantun kuta\' pasindungan a\'ana bang t\'kkahan bala\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Tinabang sigām e\' si Yawe, pinuwas e\'na min kasigpitan. Niliyus sigām e\'na min ga\'osan saga a\'a jahallis, nilappas isab sigām sabab Tuhan iya pangandolan.');
