INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Angagad na pa\'in aku ma si Yawe minsan mbal anambung saru\'un-du\'un, jari palingi\' iya ni aku bo\' akale ma panabbutku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Bay aku binuhat e\'na min kal\'bbohan, pinaluwas aku min lowang kapisakan. Pinat\'ngge aku ma batu, pinahogot pat\'nggehanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Aniya\' kalangan baha\'u pamakalangna ma aku, kalangan pamudji Tuhantam. Aheka a\'a magmatāw pag\'nda\'na ma pakaradja\'an itu, ati angandol sigām ma si Yawe.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Aheya kahāpan ma sasuku apagon pangandolna ma PANGHŪ\', ya mbal ameya\' ma saga a\'a magabbu-abbu, atawa ma a\'a ya magta\'at ma tuhan-tuhan puting!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'O Yawe, Tuhanku, aheka hinangnu makainu-inu. Mbal taitung saga kahāpan ya mohotnu ma kami. Bang aku bay pasulay anuli-nuli kamemon, mbal takole\' sinuli-suli pagga kumarukan hekana.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Ngga\'i ka tutukbalan maka tapung ya pagmatayannu, ngga\'i ka susumbali\'an tinunu\', ngga\'i ka tataubatan dusa ya kagunahannu. Saguwā\' tin\'bbok e\'nu taingaku, hatina pinakale aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Magtūy aku ah\'lling, yukku, “Itiya\' aku, sakap aku, buwat tasulat ma Kitab ma pasalanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'O Tuhanku, ahutu aku angahinang kabaya\'annu. Itiya\' ma aku sara\'nu, ma deyom pangatayanku.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Bay pasaplagku kabontol pangahandak si Yawe ma palhimpunan aheya. Kata\'uwannu asal, PANGHŪ\', halam bay tambolku bowa\'ku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Mbal tahananku ma atay kabontolnu, ah\'lling na pa\'in aku pasal kapangandolannu maka kalappasnu. Halam bay limbunganku kasi-lasanu maka kab\'nnalnu, gom pa\'in pagnasihatku ma palhimpunan aheya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Ya PANGHŪ\', da\'a pa\'in ka\'llogin ase\'nu ma aku. Hampanin aku sakahaba\' waktu maka lasanu kakkal, maka kab\'nnalannu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Sabab itiya\' aku t\'kkahan susa-manusa ya mbal taitung itiya\' aku kapilahan e\' ba\'anan dusaku. Palabi hekana min heka lamba bu\'unku, angkan aku mbal na maka\'nda\' pahāp, angahimāt pangatayanku pagka halam aniya\' pangasa.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'O PANGHŪ\', bang pa\'in aku lappasnu, O Yawe, bang pa\'in ka pasa\'ut anulung!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Bang pa\'in pinahina\' maka pinaligoto\' e\'nu saga a\'a kamemon ya anganiyat amapatay aku. Bang pa\'in hawirannu saga a\'a bilahi angamula aku, bang pa\'in sigām tahinang pagtunggīngan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Saga a\'a isab ya bay anittowahan aku, bang pa\'in sigām kapam\'ngngangan ma sabab iya\' sigām.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Saguwā\' saga a\'a ya angaholat ma ka\'a, Tuhan, bang pa\'in sigām kinōgan maka ka\'amuhan ma ka\'a. Sasuku kasulutan ma kakosog panglappasnu, subay anabbut sararan-daran: “Akawasa si Yawe! Akawasa si Yawe!”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Maka aku itu, minsan kamiskinan maka kasigpitan, kinannal isab aku he\' PANGHŪ\'. O Tuhan, ka\'a ya Mananabang maka Manglalappas ma aku, Pasa\'ut ka kono\'.');
