INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Tuhan ya patapukanta maka pangā\'anta kosog, asakap iya anabang bang aniya\' kasukkalan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Angkan kita mbal tināw minsan ajogjog dunya, minsan al\'bbos kabūd-būran tudju ni timbang.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Aho\', minsan magabal tahik, minsan amukal, minsan isab ahenggol saga būd he\' kosog haus.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Sagō\' aniya\' sapa\' anasahan amowa kakōgan ni da\'ira Tuhan, ni lugal sussi ya haddarat Tuhan Mahatinggi.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Ina\'an Tuhan ma deyom da\'irana, angkan mbal pajudjal. Pagk\'llat llaw, tinabang he\' Tuhan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Maglengogan kabangsa-bangsahan. Pah\'bba\' kapagsultanan. Angabtang sadja Tuhan, magtūy atunaw dunya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Pataptap PANGHŪ\' Sangat Kawasa ma kita, kuta\' pasindunganta ya Tuhan pangkatta si Yakub.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Dai\' kam, nda\'unbi kahinangan si Yawe, ya hinang makak\'bbal atay bay tahinangna ma dunya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Pinahondong he\'na ba\'anan pagbono\' ma kaluha\'an dunya. Pinagpōng he\'na ba\'ugan pana\', pinagp\'ppot saga budjak, Pinagtunu\' tampan sundalu ma deyom api.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, '“Pahali kam, pahati kam in aku Tuhan. Patut aku pinalanga he\' kabangsa-bangsahan. Patut aku pinalanga to\'ongan ma dunya.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Pataptap PANGHŪ\' Sangat Kawasa ma kita, Kuta\' pasindunganta ya Tuhan pangkatta si Yakub.');
