INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'O Tuhan, ka\'ase\'in aku ma sabab lasanu kakkal. Patiase\'un ka, angkan amu\'ku pinapasan paldusahanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Kose\'in aku min kasā\'anku, sussihun aku min dusaku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Sabab kata\'uwanku na kala\'atanku, mbal takalipatku, pamikilanku na pa\'in sakahaba\' waktu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Ya dusaku itu dusa ni ka\'a sadja, ngga\'i ka dusa ni manusiya\'. B\'nnal, bay aku amakay dusa ni ka\'a, angkan taluwa\' bang aku katōngannu dusa. Abontol ka. Taluwa\' isab bang aku pat\'nna\'annu hukuman.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Tantu aku dusahan waktu lagi\' kapaganak ma aku, dusahan aku min waktu kapangiraman ina\'ku ma aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Tantu isab, ya kabaya\'annu subay aniya\' kab\'nnalan sampay min deyom atay. Ya pamandu\'nu pasal pangita\'u itiya\' pasobsob ni itikadku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Sussihun aku maka sayul hissup, ati alanu\' aku. Pandihun aku, ati apote\' aku min pote\' gapas.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Pakalehun aku lling pagkoyagan, paglasigan. Pakōrun kuwat-anggauta\'ku, ya bay pinananaman kakagit ataynu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'O Tuhan, bang pa\'in ka pakeleng min paldusahanku, maka papasin kasā\'anku kamemon.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Paniya\'in aku atay sussi, pabaha\'uhun itikadku bo\' mbal magpinda-pinda.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Da\'a kono\' aku paluwasun min haddaratnu. Da\'a la\'anin min aku Rū-nu Sussi.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Pabīngun ni aku kalasigan ya bay ma aku tagna\' kapangalappasnu ma aku. Buwanin aku kajarihan ahutu bo\' tahinangku kabaya\'annu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Jari pandu\'anku saga a\'a ya angalanggal sara\'nu, pandu\'anku sigām pasal kaul-pi\'il ya makasulut ataynu. Ati aniya\' saga a\'a dusahan pabalik ni ka\'a.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'O Tuhan, ka\'a Tuhan Manglalappas, puwasin aku min dusa amapatay a\'a ati angalang aku pasal kabontol pangahandaknu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'O Tuhan, PANGHŪ\', pakalangun aku, bo\' ka sanglitanku labay min suwalaku,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Bang pagkulban ya kabaya\'annu, bay du ka bowahanku. Mbal ka kasulutan ma susumbali\'an pinagtunu\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Ya huhulmatan pagmatayan Tuhan, ya na atay ata\'u magsusun. O Tuhan, mbal sowaynu atay pagsususun maka atay areyo\'-deyo\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Bangunun da\'ira Siyun ma sabab lasanu hilas. Pahāpun tambak batu ya bay pangād ma da\'ira Awrusalam.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Minnē\' aniya\' tutukbalan abontol pangahulmat ka\'a. Aniya\' susumbali\'an pinagtunu\' ma katibu\'ukanna, maka aniya\' sapi\' l\'lla pinagkulban ma panukbalan ya ma luma\'nu.');
