INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Ya Tuhan, kalehun panangisku, taima\'un pangamu\'-ngamu\'ku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Angalingan aku ni ka\'a min lahat ya katapusan alawak pagka halam aniya\' holatanku. Malimin aku ni batu alanga ya mbal ta\'abutku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Sabab ka\'a ya bay patapukanku, ibarat kuta\' mbal tasōd e\' saga bantaku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Landu\' aku bilahi pat\'nna\' ma Luma\' Pangarapan ni ka\'a bo\' magluma\' mailu sat\'ggolku allum, ati pasindung aku ma deyo\' kepetnu sapantun anak manuk.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Ya Tuhanku, tasambutnu bay janji\'ku ma ka\'a, ati kabuwanan aku kahāpan ya pamusaka\'nu ma sasuku magmatāw ma ōnnu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Bang pa\'in pataha\'nu umul sultan, bang pa\'in pahogotnu pagsultanna sampay ma panubu\'na.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Mura-murahan, bang pa\'in iya magsultan ma matahannu salama-lama tahun. Hampanin iya pahāp ma sabab lasanu maka janji\'nu ya mbal magkapinda.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Jari aku itu angalang na pa\'in pamudjiku ōnnu, ati suhulku ai-ai bay panganajalku ma ka\'a, tukbalanku ni ka\'a kahaba\' llaw.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, '');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, '');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, '');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, '');
