INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, '');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'O Tuhan, ka\'a ya Tuhanku, landu\' aku angentom ma ka\'a. Bang aku alawak min haddaratnu, ya sapantunna lahat paslangan halam aniya\' bohe\'na. Patay bohe\' palnyawahanku, apanggang baranku ma sabab katuyu\'ku ma ka\'a.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Bay ka ta\'nda\'ku ma deyom Luma\' Pangarapan ka\'a, bay ta\'nda\'ku kawasanu maka sahayanu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Ahalga\' lasanu, labi ahalga\' min kallumku, angkan ka sanglitanku luwas min k\'llongku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Pudjiku ka sat\'ggolku allum. Anangga aku hinabuku anabbut ōnnu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Asalamat nyawaku, sapantun a\'a asso he\' kinakan ahāp lanabna, angkan aku angalang pamudji ka\'a luwas min k\'llongku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Taentomku ka\'a hinabuku palege ma pabahakanku, ati ka\'a ya paghona\'-hona\'ku kahaba\'-kahaba\' sangom.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Ka\'a ya anabangan aku, angkan aku tabowa angalang hinabuku pasindung ma pikpiknu, sali\' manuk-manuk.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Pabalut pangatayanku ma ka\'a, pinatotog aku he\' tangannu sakap kowan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Bang pa\'in palurus ni kalaloman ahirat saga a\'a ya magisun amapatay aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Bang pa\'in sigām tinugutan binono\' patay kalis bo\' pinagkakan he\' saga ero\' paslangan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Pagubus, magkalasigan sultan ma Tuhan. Sinanglitan isab Tuhan e\' sasuku anganjanji\' ma ōnna. Malaingkan pinakittup bowa\' saga a\'a magputing.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, '');
