INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Ka\'am kamemon ma dunya, olanginbi Tuhan ma sabab kakoyagbi!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Magkalang kam pamaheyabi ōnna kawasahan! Pudjihunbi iya bo\' pasōng kabantuganna!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Amissala kam ni Tuhan, yukbi, “Ya Tuhan, akawasa du pa\'in kahinangannu, mbal tasipat! Magpatiata saga palbantahannu ni ka\'a sabab kawasanu mbal tasagga\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Pasujud ni ka\'a sabarang bangsa ma deyom dunya. Angalang sigām pananglit ka\'a, pinudji ōnnu ma kalangan sigām.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Pi\'itu kam ang\'nda\' ma bay tahinang he\' Tuhan. Makatāw-tāw saga kahinangan ya tahinang e\'na pangahāp kitam panubu\' si Mbo\' Adam.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Ya tahik bay tahinang he\'na katoho\'an, bo\' magtinape\' saga a\'a parambila\'. Angkan kitam subay magkōg-koyagan Tuhan,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'ya magparinta sampay saumul-umul ma sabab kawasana. Pineyanan he\'na palbangsa-bangsahan, supaya halam aniya\' min sigām angatu ma iya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Ka\'am saga bangsa, pudjihunbi Tuhantam, patanogunbi suwalabi pananglit ma iya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Niliyusan kitam min kamatay, pineyanan kitam bo\' mbal parasdas tape\'tam.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Bay kami sulayannu, Tuhan, bay kami tatabnu, sapantun pilak tinatab ma panarulan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Bay kami kalabusunu, sapantun daing ma pokot, bay kami patanggungnu tanggungan abuhat.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Makahantak pa\'in kami, bay tugutannu saga a\'a angura\' palabay min kōk kami. Bay kami palabay isab min deyom api maka min bohe\', arak amatay, manda\' kami paluwasnu bo\' pinasampay ni lahat magdayas-dayas ma kinakan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Pi\'ilu aku ni luma\'nu angungsuran pagkulban tinunu\', maka hinangku bay pagnajalku ni ka\'a.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Hinangku in janji\' bay kak\'bbatan bowa\'ku, hinabuku bay kasigpitan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Tukbalanku ni ka\'a bili-bili al\'mmok maka kambing l\'lla tinunu\' ma katibu\'ukanna. Ungsuranku ni ka\'a susumbali\'an sapi\' maka kambing.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Sasuku kam magmatāw ma Tuhan, pi\'itu kam akale ati pangahakaku ma ka\'am bay kahinanganna ma aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Bay aku parahing ni iya, bay iya sanglitanku maka pangallam bowa\'ku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Abila aku bay anganapsuhan la\'at ma deyom atayku, mbal aku kinale he\' Panghū\'ku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Saguwā\' tantu aku kinale he\' Tuhan, ta\'asip e\'na pangamu\'-ngamu\'ku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Pudjitam Tuhan, ya halam bay amabiyal pagduwa\'aku, ya halam bay pahali alasahan aku.');
