INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Ya PANGHŪ\', Tuhan Sangat Kawasa! Kalingkat du pa\'in pat\'nna\'annu ilu!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Sali\' aku apunung e\' baya\'ku pi\'ilu ni halaman luma\' PANGHŪ\'. Magkalang aku ni Tuhan kakkal ma sabab kakōranku, luwas min palnyawahanku maka min ginhawa-baranku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Minsan saga manuk-manuk paupit makabāk pat\'ppakan ma atag paghinangan kulban ni ka\'a. Sampay saga manuk-manuk baliyu makahinang pugaranna mailu pangint\'llohanna. Ya PANGHŪ\', Tuhan Sangat Kawasa! Ka\'a ya Sultanku, ka\'a ya Tuhanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Aheya kahāpan sasuku pat\'nna\' ma deyom luma\'nu, sabab makasanglit sigām ma ka\'a ma halam aniya\' hogga\'anna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Aheya kahāpan ma sasuku makasambut kosog min ka\'a, ya angangut patukad ni Awrusalam bo\' anambahayang.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Pasalta\' sigām palabay min l\'bbak Baka, tahinang lugal pagbohe\'an. Ta\'abut pa\'in waktu pangulan, ap\'nno\' l\'bbak inān e\' kalowang-lowangan taga-bohe\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Paganap na pa\'in kosog sigām, bo\' paganap, sampay sigām paharap pakaniya-kaniya ni Tuhan ma da\'ira Siyun.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Ya PANGHŪ\', Tuhan Sangat Kawasa, Tuhan si Yakub, bang pa\'in sambutnu pangamu\'-ngamu\'ku itu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'O Tuhan, nda\'un gi\' sultan ya makatampanan kami. Nda\'un pamaihu\'anna, in iya a\'a tapene\'nu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Aku itu, pād-pād dangibu llaw maingga-maingga lahat, gom lagi\' dang\'llaw ma deyom halaman luma\'nu. Pād-pād aku pat\'nna\' ma kaluma\'an saga a\'a jahulaka\', gom lagi\' ma luma\'nu, minsan hal an\'ngge ma atag bowa\' lawang.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Sabab Tuhan Yawe sali\' ād maka tampan ma saga a\'ana. Amuwan iya hulmat maka mahaltabat. Sasuku ahongpot tebongna mbal kinaiskutan he\' Tuhan ai-ai ahāp.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'O Tuhan Sangat Kawasa aheya kahāpan ma sasuku angandol ma ka\'a.');
