INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Sasuku pat\'nna\' ma sindungan Tuhan Mahatinggi pahali-hali ma limbuhan Sangat Kawasa.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Buwattitu pah\'llingku, “Si Yawe ya pahogotanku. Sapantun iya kuta\' patapukanku, pangandolanku iya.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Tantu iya amuwasan ka\'a min jallat ya pinat\'nna\'an ka\'a, maka min saki makapatay.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Tinambunan ka e\'na ma sabakanna, ibarat manuk. Pasindung ka ma deyo\' pikpikna. Tuhan ya sapantun ād makahampanan ka\'a sabab mbal to\'ongan apinda kajarihanna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Mbal kagawahannu bangsa magl\'l\'ngngan ma kalendoman, atawa budjak ya nihiyak waktu llaw.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Mbal isāb katāwannu saki maglunsulan ma sangom, atawa bonglay ya makalaglag bang ugtu llaw.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Abugtang pa\'in dangibu a\'a ma atagnu kowan, sangpū\' ngibu pa\'in ma atagnu gibang, mbal ka talapay.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Ta\'nda\' hal he\' matanu bang ai panungbas Tuhan ma saga a\'a jahulaka\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Bang Tuhan Mahatinggi ya pataptapannu, hatina si Yawe ya patapukanku isab,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'mbal ka t\'kkahan bala\', mbal sinekot luma\'nu he\' saki bonglay,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'sabab aniya\' saga mala\'ikat sinō\' he\' Tuhan angahampanan ka\'a pi\'ingga-pi\'ingga pal\'ngnganannu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Tinayak ka e\' sigām bo\' mbal makasantuk tape\'nu ni batu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Gi\'ikannu halimaw maka sowa d\'ppong, kagindasan e\'nu halimaw maka buwaya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Angallam si Yawe, yukna, “Alasa a\'a itu ma aku, angkan liyusku iya min kajahatan, Angaku iya ma ōnku, angkan iya hampananku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Pagsabbutna ma aku, sambunganku magtūy. Pataptap aku ma iya hinabuna ma deyom sukkal. Tabangku iya ma deyom kasigpitan, maka buwananku iya ōn abantug.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Ka\'amuhan iya pagga pataha\'ku umulna. Pata\'uku iya bang buwattingga pangalappasku.”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, '');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, '');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, '');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, '');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, '');
