INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Si Yawe ya magsultan ma kamemon, pagmahaldika\'an sultan mahatinggi ya pamakayna. Ga\'osan sultan iya pakambot hawakanna. Magsin\'mmek iya kamahaltabatan. Ahogot papagan dunya itu, mbal tajudjal.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Ya Tuhan, ahogot kapagsultannu, sangay min awal tagna\'. Ka\'asalnu dahū gi\' min kapamapanjari dunya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'O Yawe, ang\'llub saga s\'llang, angabal tahik, alandos pangabalna, angalagublub kalumbagan tahik.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Landu\' aheya pangulattub goyak, aheya isab pang\'llub goyak pasampoyak. Saguwā\' labi lagi\' aheya ga\'osan si Yawe, ya katapusan alanga.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Atantu pangahatulnu, mbal magpinda-pinda. Alingkat luma\'nu e\' kasussina. Alingkat ni kasaumulan, O PANGHŪ\'.');
