INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Dai\' na kam, magkalang kitam ni si Yawe kabowa kakōgan, Patanogtam suwalatam ni iya, ya pinagsambatan Batu-Lakit panglappasan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Sūng kitam anukbal pagsukulan ni iya, paheyatam iya labay min kalangan maka tarasul.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Sababna si Yawe ya Tuhan makaga\'os, sultan abantug, alanga min katuhan-tuhanan kamemon.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Tinayak he\'na po\'onan dunya itu. Dapuna asal saga kapussukan būd.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Suku\'na asal saga katahikan, sabab iya ya bay amapanjari. Iya na isab bay angompol gintana\'an.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Dai\' na kam, pasujud kitam amudji iya. Angōk-tu\'ut kitam ma alopan PANGHŪ\' Magpapanjari,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'kalna\' in iya pagtuhanantam, maka kitam saga a\'ana, sapantun bili-bili ma pangipatanna. Na, ma llaw itu, bang takalebi bissala Tuhan, yukna,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '“Da\'a patuwasunbi kōkbi buwat bay ka\'mbo\'-mbo\'anbi ma Meriba, buwat bay ma Massa isab, ma lahat paslangan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Bay aku sinulayan maka tinukas he\' ka\'mbo\'anbi, sinulayan aku he\' sigām, minsan du bay kalabayan he\' sigām kahinanganku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Mpatpū\' tahun bay kap\'ddi\' atayku ma pangkatan ina\'an-i. Saga a\'a itu,” yukku, “mbal makatotog ameya\' ma aku. Halam tata\'u e\' sigām kaul-pi\'il ya kabaya\'anku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Bay akagit atayku ati pagsapahanku sigām,” yukku, “Saga a\'a itu mbal to\'ongan pasōd ni lahat pahalian bay tagamaku.”');
