INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Ka\'am kamemon ma dunya itu, patanogun suwalabi amudji si Yawe, kabowa kakōganbi.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Ta\'atunbi PANGHŪ\' -Yawe luwas min kakoyaganbi, pabaihu\' kam ma iya maka kalanganbi makalasig.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Ta\'uhunbi si Yawe, in iya Tuhan. Si Yawe ya bay amapanjari kitam, ati suku\'na kitam. A\'ana kitam, sapantun bili-bili ma pangipatanna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Palabay kam min saga lawangna salta\' kam magsarang-sukul. Pasōd kam ni halaman luma\'na hinabubi magpudji. Pagsukulinbi iya, pudjihunbi ōnna!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Sabab ahāp kasuddahan PANGHŪ\', maka taptap lasana kasi. Kapangandolan iya salama-lama tahun.');
