INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Pudjiku si Yawe min deyom pangatayanku. Pudjiku ōnna sussi min palnyawahanku maka min kuwat-anggauta\'ku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Aho\', pudjiku PANGHŪ\' min deyom pangatayanku, mbal takalipat kamemon kahāpan ya bay pamuwanna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Sabab iya ya angampun kamemon paldusahanbi. Iya ya amauli\' kamemon sakibi.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Iya isāb angal\'kkat kallumbi min lahat kamatayan. Iya isab amalipatan ka\'am lasa maka ase\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Iya ya amuwanan ka\'am ginisan kahāpan ya makahāp palasahanbi, angkan tabawi\' bay kosog kabata\'bi. Sapantun kam belle\' ya mbal ata\'u binale\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Abontol PANGHŪ\' -Yawe ma kahinanganna kamemon, pinabontol e\'na hukuman ma sasuku pininjala\' e\' sara\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Bay pata\'una si Musa pasal kaniyatanna. Bay pa\'nda\'na hinangna ni bangsa Isra\'il.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Patiase\'un maka patilasahun asal PANGHŪ\' -Yawe, mbal akagit atayna magdai\'-dai\', gom pa\'in palabi lasana tuman.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Mbal iya paddas amabukag, mbal anatas ka\'astolna sampay ni kasaumulan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Mbal kita pinat\'nna\'an kabinasahan ya makatōpan dusata. Mbal kita tinungbasan e\'na ma buwat hinangta ala\'at.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Sabab-kalna\', landu\' aheya lasana ma sasuku magmatāwan iya. Mbal tabista kaheya lasana itu, buwat diyata\' langit mbal tabista langkawna min babaw dunya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Pinalawak e\'na paldusahantam, buwat lawak sobangan maka s\'ddopan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Aheya ase\' ma sasuku magmatāw ma iya, buwat ka\'ase\' matto\'a ma panganakna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Sabab kinata\'uwan asal e\'na ya bay pangompolan kitam manusiya\'. Taentomna in kitam bay nihinang min bagunbun tana\'.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Ya niōnan manusiya\' itu mbal anatas, sapantun parang-parang dai\'-dai\' patubu\'. Sapantun sumping huma dai\'-dai\' manisna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Pagtumbuk pa\'in baliyu, magtūy halam na. Mbal taentom bay kamahē\'na.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Malaingkan ya kasi-lasa PANGHŪ\' ni sasuku magmatāw ma iya anatas min awal tagna\' sampay ni kasaumulan. Pasampay kahandakna abontol ni anak-mpu saga a\'a kamemon,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'sasuku amogbogan kapagsulutan sigām maka Tuhan, maka atukid ameya\' ma pandu\'na.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Pinatuman e\' si Yawe pagparintana ma sulga\' ati magtuhan iya ma papanjarihanna kamemon.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Pudjihunbi PANGHŪ\' -Yawe, ka\'am saga mala\'ikatna patikawasahun ya angahinang kahandak Tuhan, ya ameya\' ma panoho\'anna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Pudjihunbi PANGHŪ\', ka\'am kalaksa\'-laksa\'an ya sosoho\'anna ma deyom sulga\', maka ka\'am ya maghinang kabaya\'anna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Pudjihunbi PANGHŪ\', ka\'am papanjarihanna, pudjihunbi iya maingga-maingga ma pagparintahanna. Pudjiku isab PANGHŪ\' sampay min buli\'-atayku.');
