INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Aheya kahāpan ma sasuku mbal katōngan dusa, ya atukid ameya\' ma bay panara\' si Yawe.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Aheya kahāpan ma saga a\'a ya magkahagad ma pandu\'na, ya magmatayan Tuhan sadja.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Mbal sigām angahinang kala\'atan, gom pa\'in sigām an\'ppu kajarihanna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'O PANGHŪ\', bay ka amat\'nna\'an kami hatulan ya wajib bineya\' to\'ongan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Mura-murahan bang pa\'in aku makatuyu\' ameya\' ma ai-ai pangahandaknu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Mbal aku tahinang pagiya\'an, bang tahona\'-hona\'ku panoho\'annu kamemon.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Pudjiku ka magatay pote\', hinabuku angadji\' panara\'nu ya landu\' abontol.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Ameya\' du aku ma pangahandaknu, da\'a pa\'in aku siya-siyahun.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Buwattingga he\' subul anussi kajarihanna? Luwal bang panunuranna palmannu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Ka\'a ya pagmatayanku, Tuhan, da\'a aku tugutin pasā\' min panoho\'annu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Tatau\'ku palmannu ma deyom pangatayanku bo\' supaya mbal amakay dusa ni ka\'a.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'O Yawe, bang pa\'in aheya barakat ma ka\'a, pandu\'in lagi\' aku pasal kahandaknu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Usulku na pa\'in saga panara\' bay pangallamnu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Kinōgan aku ameya\' ma pandu\'nu, buwat a\'a magkōgan pangalta\' aheya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Panoho\'annu ya pagtali\'anku kahaba\' waktu, pamikilanku na pa\'in kajarihannu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Ka\'amuhan aku ma pangahandaknu, mbal palehomku palmannu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Pagmurahun sosoho\'annu itu, ati allum aku, maka amogbog pahāp ma palmannu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Pasawahun lagi\' pikilanku bo\' ahāp e\'ku ang\'nda\' ma sara\'nu makainu-inu.');
