INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'O PANGHŪ\', palmannu itu sapantun palita\'an ma pal\'ngngananku, suwariyan ma labayanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Bay aku makasapa maka bay patumanku, in aku ameya\' to\'ongan ma panara\'nu, ya adil lullun.');
