INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Makainu-inu pamandu\'nu, angkan bogboganku to\'ongan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Palmannu ya pangā\'an sawa pamaranta\' pikilan manusiya\', minsan a\'a akulang pangadji\'na makahati du isab.');
