INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Pahangad aku ang\'nda\' tudju ni kabūran. Minningga aku makabāk tabang?');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Tinabang aku he\' si Yawe, ya bay amapanjari langit maka dunya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Mbal pasagaranna tape\'nu parasdas ma lān. Mbal tatuli ya anganjagahan ka\'a.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Mbal talilap ya anunggu\'an bangsa Isra\'il, tantu iya mbal tatuli.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Si Yawe ya anganjagahan ka\'a, pasindungannu si Yawe pataptap ma bihingnu kowan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Mbal ka kinapiyalu bang llaw, mbal ka taluwa\' bulan bang sangom.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'PANGHŪ\' -Yawe ya angahampanan ka\'a bo\' mbal ta\'abut la\'at. PANGHŪ\' ya ameyanan kallum-nyawanu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'PANGHŪ\' ya anganjagahan ka\'a ma katulaknu maka ma kapole\'nu, min llaw itu sampay ni kasaumulan.');
