INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'O Yawe, bay aku tatabnu, kata\'uwannu aku maka kapaga\'aku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Ata\'u ka ma katingkō\'ku maka ma kapundukku, kasakupannu pamikilku minsan min kalawakan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Ata\'u ka ma kalunsulku maka kalegeku, tahimangkannu kajarihanku kamemon.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'O Yawe, bang aku sōng amaluwas bissala, asal kata\'uwannu kamemonna ma halam gi\' tak\'bbat.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Nilikusan aku e\'nu min dahuwan maka min bukutan, kapat\'nna\'an aku tangannu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Landu\' makahaylan pangita\'u buwattilu, mbal takannalku. Landu\' alanga, mbal ta\'abutku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Ya PANGHŪ\', pi\'ingga aku bo\' makalahi min Rū-nu? Pi\'ingga palahianku bo\' kaillaganku haddaratnu?');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Bang aku pa\'angkat ni langit diyata\', mailu ka asal. Bang aku pabahak ma lahat kamatay, mailu isab ka.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Bang aku paleyang ni pasobangan llaw ati maglahat aku ma dambila\' s\'llang,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'ina\'an ka isab angamaliman aku, komkomannu aku maka tangannu sakap kowan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Bang aku angupama, yukku, “Tantu aku katambunan e\' kalendoman, papinda isab llaw ni sangom ma katilibutku,”');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'halam aniya\' dapat, sabab halam aniya\' lendom ma ka\'a. Minsan sangom anahaya sali\' llaw, sabab sali\' du lendom maka sawa bang ma ka\'a.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Ka\'a PANGHŪ\', bay amapanjari ginhawa-baranku, tabatuk e\'nu pagdayawku hinabuku lagi\' ma deyom kandang ina\'ku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Aheya pudjiku ni ka\'a, sabab ainu-inu aku, sinōd aku tāw, ma sabab ginhawa-baran ya hinangannu aku. Tata\'uku asal, makainu-inu kahinangan kamemon.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Halam katapukan min ka\'a pagdayaw baranku waktu lagi\' kapagbatuk ma aku ma kuta\' kuddarat. Waktu isab kapanganyam ma aku ma kalaloman gumi,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'ta\'nda\'nu aku ma halam gi\' ajukup kapaga\'aku. Tasulat asal saga llaw ya pangangganta\'nu ma aku, tasulat ma deyom kitabnu, tasulat dahū lagi\' min llaw kalahilku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Ya Tuhan, ahalga\' ma aku kahona\'-hona\'nu, kumarukan hekana, mbal tasipat.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Bang aku angitung kahona\'-hona\'annu, paheka lagi\' min solagan gusung ma kaluha\'an dunya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Ya Tuhan, bang pa\'in papataynu saga a\'a jahallis! Ka\'am saga bula\'ug, ala\'an kam min aku!');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Tuhan, pinamūng-mūngan ka pangkal e\' saga a\'a inān, pinahina\' ōnnu e\' palbantahannu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'O Yawe, aheya kab\'nsiku ma sasuku ab\'nsihan ka\'a. Sasuku angatu ma kapagbaya\'nu, asammal ma pang\'nda\'ku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Mbal kasandalan kab\'nsiku ma saga a\'a inān, itungku sigām sali\' bantaku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'O Tuhan, lilingun aku bo\' tata\'unu deyom pangatayanku, tatabun aku bo\' tata\'unu bang ai kahanggawanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Tandingun aku, ya aniya\' makala\'at ma iman-nyawaku, ati malimin aku ma lān ya kakkal min awal ni ahil.');
