INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'O Yawe, kalehun lagi\' pangamu\'-ngamu\'ku. Kalehun panganjunjungku, ka\'ase\'in aku. Pasa\'ut ka kono\' anabangan aku, sabab kapangandolan ka maka abontol.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Aku itu sosoho\'annu, da\'a aku sara\'un, sabab halam aniya\' manusiya\' abontol ma pang\'nda\'nu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Tinurul aku he\' bantaku, ginindasan aku e\'na, pinodjak aku. Pinat\'ddas aku he\'na ma deyom kalendoman, sapantun a\'a at\'ggol na kamatayna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Halam aniya\' kaholatanku, alamma palnyawahanku, angaloyot pangatayanku kabowa sukkalna.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Amagtak ni atay saga patahunan palabay, angahona\'-hona\' aku pasal kahinangannu, amikil-mikil pasal hinang tangannu kamemon.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Jari anangga aku tudju ni ka\'a, mbal kasandalan pagmatay ma ka\'a, sapantun a\'a patay bohe\' ma lahat apanggang.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'O PANGHŪ\', pasa\'ut lagi\' ka anambung, sabab angalongkoy iman-nyawaku. Bang ka pataikut min aku, tantu aku pasali\' ni saga a\'a ya amole\' lahat.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Bang pa\'in aniya\' habal pagdai\'-llaw angalapalan aku pasal lasanu kakkal, sabab angandol du aku ma ka\'a. Pandu\'in aku lān ya wajib pal\'ngngananku, sabab ka\'a ya pangaholatan palnyawahanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'O Yawe, liyusun aku kono\' min saga bantaku, sabab ka\'a ya patapukanku.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Pandu\'in aku bo\' tabeya\'ku ai-ai pangahandaknu aku, sabab ka\'a ya Tuhanku. Bang pa\'in aku minaliman he\' Rū-nu ahāp, supaya aku makal\'ngngan ma lān aratag.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Ya PANGHŪ\', pakallumun aku ma sabab kabantug ōnnu. Puwasin aku min kasukkalan ma sabab kabontol palangaynu.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Laglagun lagi\' palbantahanku ma sabab lasanu kakkal. Pahalamun saga a\'a kamemon ya anguntarahan aku, sabab atanu du aku.');
