INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Pudji ni si Yawe! Pudjihunbi iya min deyom sulga\', pudjihunbi min kalangahan langit.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Ka\'am saga mala\'ikatna, pudjihunbi iya, ka\'am sosoho\'anna patikawasahun, pudjihunbi.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Ka\'am mata llaw maka bulan, pudjihunbi si Yawe, ka\'am saga bitu\'un magsasahaya, pudjihunbi iya.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Saga ma kalangkawan katapusan, amudji kam ma iya, Saga bohe\' ma diyata\'an langit, amudji kam.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Patut pinabantug ōn si Yawe e\' ai-ai pinapanjari sabab angallam sadja iya ati paniya\' magtūy.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Pinat\'nna\'an sigām lugal min kahandakna, pinat\'nna\'an sigām ganta\'an ya anatas ni kasaumulan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Pudjihunbi si Yawe ma kaluha\'an dunya, ka\'am saga sattuwa maka sasuku ma kategob-tegoban,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'l\'tte\' maka tigtigan aes, alu\' aes maka gabun, saga badju ya angahinang kabaya\'anna,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'kamemon kabūd-būran maka kabīd-bīran, saga kabbun maka saga kayu sidro,');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'kaginisan sattuwa talun maka kamemon sapi\' ni\'ipat, manuk-manuk palē maka manuk-manuk pikpikan');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'saga kasultanan ma dunya maka palbangsa-bangsahan, saga a\'a balbangsa maka saga magbabaya\',');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'saga onde\' baha\'u subul-budjang, kamanahutan maka kato\'ahan.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Papudjihun kamemon pinapanjari itu, soho\'un amabantug ōn si Yawe sabab luwal ōnna ya patut binantug. Minsan maingga ma dunya, minsan isab ma sulga\' halam aniya\' makaliyu min kamahaldika\'an si Yawe.');
INSERT INTO `sml_BL_2008_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Aniya\' a\'a patikosogun pinaniya\' e\'na panabang saga a\'ana, a\'a pinagmahaltabatan e\' kamemon suku\'na, e\' saga panubu\' si Isra\'il, ya bangsa kalasahanna.');
